import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** Opens and initializes the SQLite database shared by both processes. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA busy_timeout = 5000;
    PRAGMA journal_mode = WAL;
    PRAGMA synchronous = NORMAL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY,
      status TEXT NOT NULL CHECK(status IN ('queued','running','completed','failed')),
      input TEXT NOT NULL,
      steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0,
      result_output TEXT,
      error TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      next_run_at INTEGER NOT NULL DEFAULT 0,
      idempotency_key TEXT UNIQUE,
      payload_json TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS jobs_queue_idx ON jobs(status, next_run_at, created_at);
    CREATE TABLE IF NOT EXISTS worker_heartbeat (
      id INTEGER PRIMARY KEY CHECK(id = 1),
      seen_at INTEGER NOT NULL
    );`);
  return db;
}

export function toJob(row: Record<string, unknown>): Job {
  return {
    id: String(row.id), status: row.status as JobStatus, input: String(row.input),
    steps: Number(row.steps), failAttempts: Number(row.fail_attempts), attempts: Number(row.attempts),
    progress: { completed: Number(row.progress_completed), total: Number(row.steps) },
    result: row.result_output === null ? null : { output: String(row.result_output) },
    error: row.error === null ? null : String(row.error),
    createdAt: String(row.created_at), updatedAt: String(row.updated_at),
  };
}

export function nowIso(): string { return new Date().toISOString(); }
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, nowIso } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A process that died during a job leaves the durable row in running state. Queue it
// for a fresh attempt as soon as this worker starts.
db.prepare(`UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, next_run_at=0 WHERE status='running'`).run(nowIso());
const heartbeat = db.prepare(`INSERT INTO worker_heartbeat (id,seen_at) VALUES (1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at`);
heartbeat.run(Date.now());
const heartbeatTimer = setInterval(() => {
  try { heartbeat.run(Date.now()); } catch (err) { console.error('heartbeat update failed', err); }
}, 500);

interface QueueRow { id: string; input: string; steps: number; fail_attempts: number; attempts: number }
const claimNext = db.prepare(`SELECT id,input,steps,fail_attempts,attempts FROM jobs
  WHERE status='queued' AND next_run_at <= ? ORDER BY created_at ASC, rowid ASC LIMIT 1`);

function claim(): QueueRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = claimNext.get(Date.now()) as QueueRow | undefined;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const updated = db.prepare(`UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0,
      result_output=NULL, error=NULL, updated_at=? WHERE id=? AND status='queued'`).run(nowIso(), row.id);
    db.exec('COMMIT');
    if (Number(updated.changes) !== 1) return undefined;
    return { ...row, attempts: Number(row.attempts) + 1 };
  } catch (err) { db.exec('ROLLBACK'); throw err; }
}

async function runJob(job: QueueRow): Promise<void> {
  if (job.attempts <= Number(job.fail_attempts)) {
    // The simulated dependency fails at the first step, before progress is recorded.
    if (job.attempts >= 3) {
      db.prepare(`UPDATE jobs SET status='failed', error='transient failure', result_output=NULL,
        progress_completed=0, updated_at=? WHERE id=? AND status='running'`).run(nowIso(), job.id);
    } else {
      db.prepare(`UPDATE jobs SET status='queued', error=NULL, progress_completed=0, next_run_at=?, updated_at=?
        WHERE id=? AND status='running'`).run(Date.now() + 500, nowIso(), job.id);
    }
    return;
  }

  const updateProgress = db.prepare(`UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'`);
  for (let completed = 1; completed <= Number(job.steps); completed++) {
    await sleep(100);
    updateProgress.run(completed, nowIso(), job.id);
  }
  const output = String(job.input).toUpperCase();
  db.prepare(`UPDATE jobs SET status='completed', result_output=?, error=NULL, progress_completed=?, updated_at=?
    WHERE id=? AND status='running'`).run(output, job.steps, nowIso(), job.id);
}

console.log('worker started');
try {
  while (!stopping) {
    const job = claim();
    if (!job) { await sleep(100); continue; }
    try { await runJob(job); }
    catch (err) {
      console.error('job processing failed', err);
      // Unexpected processing errors use the same bounded retry path.
      const current = db.prepare('SELECT attempts FROM jobs WHERE id=?').get(job.id) as { attempts: number } | undefined;
      if (current && Number(current.attempts) >= 3) {
        db.prepare(`UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at=? WHERE id=?`)
          .run(nowIso(), job.id);
      } else {
        db.prepare(`UPDATE jobs SET status='queued', error=NULL, progress_completed=0, next_run_at=?, updated_at=? WHERE id=?`)
          .run(Date.now() + 500, nowIso(), job.id);
      }
    }
  }
} finally {
  clearInterval(heartbeatTimer);
  // Marking the heartbeat stale makes health accurate immediately after a graceful stop.
  db.prepare('DELETE FROM worker_heartbeat WHERE id=1').run();
  db.close();
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, nowIso } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const port = Number(process.env.PORT ?? 3000);
const jobSelect = db.prepare('SELECT * FROM jobs WHERE id = ?');
const listJobs = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: Array<{field:string;message:string}>): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
function fieldError(field: string, message: string) { return { field, message }; }

async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const b = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    size += b.length;
    if (size > 1024 * 1024) throw new Error('body too large');
    chunks.push(b);
  }
  return Buffer.concat(chunks).toString('utf8');
}

function validate(value: unknown): { payload?: { input: string; steps: number; failAttempts: number }; fields: Array<{field:string;message:string}> } {
  const fields: Array<{field:string;message:string}> = [];
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return { fields: [fieldError('body', 'must be a JSON object')] };
  }
  const body = value as Record<string, unknown>;
  for (const key of Object.keys(body)) if (!['input','steps','failAttempts'].includes(key)) fields.push(fieldError(key, 'is not allowed'));
  if (!Object.hasOwn(body, 'input')) fields.push(fieldError('input', 'is required'));
  else if (typeof body.input !== 'string') fields.push(fieldError('input', 'must be a string'));
  else if (body.input.length < 1 || body.input.length > 1000) fields.push(fieldError('input', 'must be between 1 and 1000 characters'));
  else if (!body.input.trim()) fields.push(fieldError('input', 'must not be only whitespace'));

  let steps = 5;
  if (Object.hasOwn(body, 'steps')) {
    if (typeof body.steps !== 'number' || !Number.isInteger(body.steps) || body.steps < 1 || body.steps > 20) fields.push(fieldError('steps', 'must be an integer from 1 to 20'));
    else steps = body.steps;
  }
  let failAttempts = 0;
  if (Object.hasOwn(body, 'failAttempts')) {
    if (typeof body.failAttempts !== 'number' || !Number.isInteger(body.failAttempts) || body.failAttempts < 0 || body.failAttempts > 5) fields.push(fieldError('failAttempts', 'must be an integer from 0 to 5'));
    else failAttempts = body.failAttempts;
  }
  if (fields.length) return { fields };
  return { payload: { input: body.input as string, steps, failAttempts }, fields };
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const pathname = url.pathname;
  const isJobDetail = /^\/api\/jobs\/[^/]+$/.test(pathname);
  const known = pathname === '/' || pathname === '/health' || pathname === '/api/jobs' || isJobDetail;
  if (!known) return error(res, 404, 'not_found', 'Route not found.');
  const expected = pathname === '/' ? 'GET' : pathname === '/health' ? 'GET' : pathname === '/api/jobs' ? (req.method === 'GET' || req.method === 'POST' ? req.method : 'GET|POST') : 'GET';
  if (pathname === '/api/jobs' && req.method !== 'GET' && req.method !== 'POST' || pathname !== '/api/jobs' && req.method !== expected) {
    res.setHeader('allow', pathname === '/api/jobs' ? 'GET, POST' : expected);
    return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  }
  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    const heartbeat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1').get() as { seen_at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: heartbeat && Date.now() - Number(heartbeat.seen_at) <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const jobs = listJobs.all() as Record<string, unknown>[];
    return send(res, 200, { jobs: jobs.map(toJob) });
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const fields: Array<{field:string;message:string}> = [];
    const contentType = req.headers['content-type'];
    if (!contentType || !/^application\/json(?:\s*;|\s*$)/i.test(contentType)) fields.push(fieldError('body', 'Content-Type must be application/json'));
    const idem = req.headers['idempotency-key'];
    const key = Array.isArray(idem) ? idem[0] : idem;
    if (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key)) fields.push(fieldError('Idempotency-Key', 'must contain 1 to 128 letters, numbers, underscores, or hyphens'));
    let raw = '';
    try { raw = await readBody(req); }
    catch { fields.push(fieldError('body', 'must be valid JSON')); }
    let parsed: unknown;
    let parsedOk = true;
    if (!fields.some(f => f.field === 'body' && f.message === 'must be valid JSON')) {
      try { parsed = JSON.parse(raw); } catch { parsedOk = false; fields.push(fieldError('body', 'must be valid JSON')); }
    } else parsedOk = false;
    if (!parsedOk) return error(res, 400, 'invalid_request', 'Request validation failed.', fields);
    const checked = validate(parsed);
    fields.push(...checked.fields);
    if (fields.length || !checked.payload) return error(res, 400, 'invalid_request', 'Request validation failed.', fields);
    const payload = checked.payload;
    const payloadJson = JSON.stringify(payload);
    if (key !== undefined) {
      const prior = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as Record<string, unknown> | undefined;
      if (prior) {
        if (prior.payload_json !== payloadJson) return error(res, 409, 'idempotency_conflict', 'This idempotency key was used with a different payload.');
        return send(res, 200, toJob(prior));
      }
    }
    const id = randomUUID();
    const timestamp = nowIso();
    try {
      db.prepare(`INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,next_run_at,idempotency_key,payload_json)
        VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`).run(id, payload.input, payload.steps, payload.failAttempts, timestamp, timestamp, key ?? null, payloadJson);
    } catch (err) {
      if (key !== undefined) {
        const prior = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as Record<string, unknown> | undefined;
        if (prior) {
          if (prior.payload_json === payloadJson) return send(res, 200, toJob(prior));
          return error(res, 409, 'idempotency_conflict', 'This idempotency key was used with a different payload.');
        }
      }
      console.error('failed to create job', err);
      return error(res, 500, 'internal_error', 'Could not create job.');
    }
    return send(res, 201, toJob(jobSelect.get(id) as Record<string, unknown>));
  }
  if (isJobDetail) {
    let id: string;
    try { id = decodeURIComponent(pathname.slice('/api/jobs/'.length)); } catch { return error(res, 404, 'not_found', 'Job not found.'); }
    const row = jobSelect.get(id) as Record<string, unknown> | undefined;
    if (!row) return error(res, 404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
});

server.listen(port, () => console.log(`server listening on ${port}`));
function shutdown() { server.close(() => { db.close(); process.exit(0); }); }
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
